// 传输函数
// ---------------------------------------------------------------------------", "new_string": "// ---------------------------------------------------------------------------
// Chromium 版传输函数 (CSS 颜色值路径 —— 我们要对齐的是这条)
// ---------------------------------------------------------------------------

/// Chromium `skcms::TransferFunction_eval` (`/srv/nitoqi/nozu/tilolet:20-31`)。
///
/// 与 skcms 上游版的**五处**差异, 全部直译自源码:
/// 1. 用 `std::pow` 而非 skcms 的 `powf_` 近似 (上游版因此被 Chromium 弃用)
/// 2. 阈值是 `abs_x <= d` 而非 `abs_x < d` —— **在 x == d 处两者不同**
/// 3. 底数钳到非负: `max(a*abs_x + b, 0)`
/// 4. `g == 1` 走快路径, 不做 pow
/// 5. 用 `std::abs` 取绝对值, 而不是 `x * sign`
#[inline]
pub fn transfer_function_eval(tf: &TransferFunction, x: f32) -> f32 {
    let sign = if x < 0.0 { -1.0f32 } else { 1.0f32 };
    let abs_x = x.abs();
    if abs_x <= tf.d {
        return sign * (tf.c * abs_x + tf.f);
    }
    let base = (tf.a * abs_x + tf.b).max(0.0);
    if tf.g == 1.0 {
        return sign * (base + tf.e);
    }
    sign * (base.powf(tf.g) + tf.e)
}

/// Chromium `skcms::TransferFunction_invert` (`/srv/nitoqi/nozu/tilolet:35-71`)。
///
/// 源码注释: "a direct copy-paste of skcms_TransferFunction_invert, but with the
/// std math functions instead of the inaccurate approximations"。
pub fn transfer_function_invert(src: &TransferFunction) -> Option<TransferFunction> {
    let mut inv = TransferFunction {
        g: 0.0,
        a: 0.0,
        b: 0.0,
        c: 0.0,
        d: 0.0,
        e: 0.0,
        f: 0.0,
    };

    let d_l = src.c * src.d + src.f;
    let d_r = (src.a * src.d + src.b).powf(src.g) + src.e;
    if (d_l - d_r).abs() > 1.0f32 / 512.0 {
        return None;
    }
    inv.d = d_l;

    if inv.d > 0.0 {
        inv.c = 1.0 / src.c;
        inv.f = -src.f / src.c;
    }

    let k = src.a.powf(-src.g);
    inv.g = 1.0 / src.g;
    inv.a = k;
    inv.b = -k * src.e;
    inv.e = -src.b / src.a;

    if inv.a < 0.0 {
        return None;
    }
    if inv.a * inv.d + inv.b < 0.0 {
        inv.b = -inv.a * inv.d;
    }

    // 保住 inv(src(1.0)) == 1.0 这个不变量
    let s = transfer_function_eval(src, 1.0);
    if !s.is_finite() {
        return None;
    }
    let sign = if s < 0.0 { -1.0f32 } else { 1.0f32 };
    let s = s * sign;
    if s < inv.d {
        inv.f = 1.0 - sign * inv.c * s;
    } else {
        inv.e = 1.0 - sign * (inv.a * s + inv.b).powf(inv.g);
    }
    Some(inv)
}

// ---------------------------------------------------------------------------
// skcms 版传输函数 (像素管线路径)
// ---------------------------------------------------------------------------"}

