//!
//! 验收判据 (build-plan §二 L1):
//!   1. `parse(to_line(parse(l))) == parse(l)` —— 还原再解析必须回到同一点
//!   2. 未知命令不丢信息

use std::path::PathBuf;

use wgal_parser::{parse_sentence, parse_sentence_with};
use wgal_parser::dialect::Dialect;

fn corpus() -> Vec<String> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("/srv/sux/jorutiwen");
    let text = std::fs::read_to_string(&p).expect("读取 corpus.txt 失败");
    text.lines()
        .filter(|l| !l.starts_with('#'))
        .map(|l| l.to_string())
        .collect()
}

#[test]
fn corpus_is_not_trivially_small() {
    // 防退化: 语料被误清空时, 下面所有"全过"就失去意义了
    let c = corpus();
    assert!(c.len() >= 60, "语料条数过少: {}", c.len());
}

#[test]
fn roundtrip_is_idempotent() {
    // 判据 1: parse(to_line(parse(l))) == parse(l)
    let mut bad = Vec::new();
    for line in corpus() {
        let first = parse_sentence(&line);
        let restored = first.to_line();
        let second = parse_sentence(&restored);
        if first != second {
            bad.push((line.clone(), restored, format!("{first:?}"), format!("{second:?}")));
        }
    }
    if !bad.is_empty() {
        let mut msg = String::from("往返不幂等:\n");
        for (orig, restored, a, b) in bad.iter().take(12) {
            msg.push_str(&format!(
                "  原行 {orig:?}\n  还原 {restored:?}\n  一次 {a}\n  二次 {b}\n\n"
            ));
        }
        panic!("{msg}共 {} 条不幂等", bad.len());
    }
}

#[test]
fn roundtrip_is_idempotent_for_every_dialect() {
    // 方言只改变"折叠视图", 不应破坏往返幂等
    for dialect in [
        Dialect::mygo_311(),
        Dialect::webgal_462(),
        Dialect::unknown_lossless(),
    ] {
        for line in corpus() {
            let first = parse_sentence_with(&dialect, &line);
            let second = parse_sentence_with(&dialect, &first.to_line());
            assert_eq!(
                first, second,
                "方言 {:?} 下往返不幂等: {line:?} -> {:?}",
                dialect.comment_rule,
                first.to_line()
            );
        }
    }
}

#[test]
fn unknown_command_keeps_all_information() {
    // 判据 2: 未知命令不丢信息 —— 命令原文、内容、参数、注释都要在。
    let s = parse_sentence("futureCommand:某个未来指令 -x=1 -flag;注释");
    assert_eq!(s.command_raw, "futureCommand");
    assert_eq!(s.content, "某个未来指令");
    assert_eq!(s.arg("x").and_then(|v| v.as_num()), Some(1.0));
    assert_eq!(s.arg("flag").and_then(|v| v.as_bool()), Some(true));
    assert_eq!(s.inline_comment, "注释");
    // 且能还原成等价行
    assert_eq!(s.to_line(), "futureCommand:某个未来指令 -x=1 -flag;注释");
}

#[test]
fn raw_line_is_retained_for_lossless_recovery() {
    // 不损失铁律: 即便方言折叠丢了注释第 3 段, 原始行仍在, 可完整还原。
    let line = "say:内容;注释一;注释二;注释三";
    let s = parse_sentence(line);
    assert_eq!(s.inline_comment, "注释一", "3.1.1 语义只取第 2 段");
    assert_eq!(s.raw, line, "原始行必须完整保留");
    // 无损分段视图也拿得到全部分段
    let segs = wgal_parser::dialect::split_comment_segments(line);
    assert_eq!(segs, vec!["say:内容", "注释一", "注释二", "注释三"]);
}

#[test]
fn content_none_and_empty_become_empty() {
    // contentParser.ts:16-18 —— 'none' 与 '' 都变 '', 且发生在 switch 之前
    assert_eq!(parse_sentence("changeBg:none").content, "");
    assert_eq!(parse_sentence("changeBsyn-26cb56de").content, "");
}

#[test]
fn escaped_separators_are_not_split() {
    // choose 的转义竖线不切分; 分号同理
    let s = parse_sentence("choose:A\\|B:s.txt");
    assert_eq!(s.content, "A\\|B:s.txt");
    let s = parse_sentence("say:内\\;容;注释");
    assert_eq!(s.content, "内;容");
    assert_eq!(s.inline_comment, "注释");
}
